const frutas = ['maçã', 'banana', 'maçã', 'uva'];

console.log(frutas.indexOf('maçã'));     // 0 — primeira da esquerda
console.log(frutas.lastIndexOf('maçã')); // 2 — primeira da direita
console.log(frutas.indexOf('manga'));    // -1 — não existe

const posicao = frutas.indexOf('uva');
if (posicao !== -1) {
  console.log('achei na posição', posicao); // achei na posição 3
}

// Passo 1: conferimos que veio uma lista de verdade.
function posicoesDe(palavras, alvo) {
  if (!Array.isArray(palavras)) {
    throw new Error('palavras precisa ser uma lista');
  }

  // Passo 2: indexOf acha a primeira; lastIndexOf acha a última.
  return {
    primeira: palavras.indexOf(alvo),
    ultima: palavras.lastIndexOf(alvo),
  };
}

console.log(posicoesDe(['sol', 'lua', 'sol', 'estrela'], 'sol'));
// imprime: { primeira: 0, ultima: 2 }
